fn canon(text: &str) -> String {
    text.to_lowercase()
        .replace('ü', "u")
        .chars()
        .filter(|character| character.is_alphanumeric())
        .collect()
}

fn pretty(text: &str) -> String {
    text.replace('_', " ")
}

fn find_record(query: &str) -> Option<&'static Record> {
    let normalized = canon(query);
    RECORDS.iter().find(|item| {
        canon(item.accession) == normalized
            || canon(item.key) == normalized
            || canon(item.name) == normalized
            || item.aliases.iter().any(|alias| canon(alias) == normalized)
    })
}

fn location(item: &Record) -> String {
    if item.location_kind == "nonphysical_standard" {
        return format!("nonphysical (origin: {})", item.origin_house);
    }
    let mut segments = vec![item.house.unwrap_or(item.origin_house)];
    if let Some(district) = item.district {
        segments.push(district);
    }
    if let Some(area) = item.area {
        segments.push(area);
    }
    segments.join(" / ")
}

fn index(house: Option<&str>, register: Option<&str>) {
    println!("WARDEN REGISTRAR v0.3   |   READ ONLY");
    println!("One Registrar · Multiple Registers · Four Independent Houses");
    println!("Civic: existing / unaffected  |  Enterprise: 3  |  Institutional: 4");
    println!(
        "{:<8}  {:<23}  {:<14}  LOCATION / ORIGIN",
        "ACCESSION", "ENTITY", "REGISTER"
    );
    println!("{}", "─".repeat(92));
    let mut count = 0;
    for entry in RECORDS {
        if house.is_some_and(|selected| canon(selected) != canon(entry.origin_house)) {
            continue;
        }
        if register.is_some_and(|selected| {
            !entry
                .registers
                .iter()
                .any(|category| canon(category) == canon(selected))
        }) {
            continue;
        }
        println!(
            "{:<8}  {:<23}  {:<14}  {}",
            entry.accession,
            entry.name,
            entry.registers.join("+"),
            location(entry)
        );
        count += 1;
    }
    println!(
        "{} record(s).  Use: registrar show <id> | registrar explore | registrar help",
        count
    );
}

fn card(item: &Record) {
    println!("{}  ·  {}", item.accession, item.name);
    println!("─────────────────────────────────────────────────────────");
    if !item.aliases.is_empty() {
        println!("Also known as     {}", item.aliases.join(", "));
    }
    println!("Kind              {}", pretty(item.kind));
    println!("Register          {}", item.registers.join(", "));
    println!("Origin House      {}", item.origin_house);
    println!("Location          {}", location(item));
    println!(
        "Point             {}",
        item.point
            .unwrap_or(if item.location_kind == "nonphysical_standard" {
                "not applicable"
            } else {
                "unassigned"
            })
    );
    println!("Owner             {}", pretty(item.owner_status));
    println!(
        "Functions         {}",
        item.functions
            .iter()
            .map(|value| pretty(value))
            .collect::<Vec<_>>()
            .join(", ")
    );
    if !item.relationships.is_empty() {
        println!("Relationships:");
        for link in item.relationships {
            let target = link
                .target
                .map(str::to_owned)
                .unwrap_or_else(|| link.target_houses.join(" ↔ "));
            let role = link
                .role
                .map(|value| format!(" — {value}"))
                .unwrap_or_default();
            println!(
                "  • {} → {}{} [{}]",
                pretty(link.relation),
                target,
                role,
                pretty(link.status)
            );
        }
    }
    if !item.special_rules.is_empty() {
        println!("Special provisions:");
        for rule in item.special_rules {
            println!("  • {rule}");
        }
    }
    println!("Jurisdiction remains with the House; the Registrar indexes records only.");
}

