fn verify() -> Result<(), String> {
    if RECORDS.len() != 7 {
        return Err(format!(
            "expected 7 founding records, found {}",
            RECORDS.len()
        ));
    }
    for (position, entry) in RECORDS.iter().enumerate() {
        if entry.accession.is_empty() || entry.key.is_empty() || entry.name.is_empty() {
            return Err("founding entry with missing identifier".into());
        }
        if !["Stonebend", "Sandmanor", "Glaüshouse", "Flynt"].contains(&entry.origin_house) {
            return Err(format!("unknown House in {}", entry.accession));
        }
        if RECORDS
            .iter()
            .skip(position + 1)
            .any(|other| other.accession == entry.accession || other.key == entry.key)
        {
            return Err(format!(
                "duplicate registry key or accession: {}",
                entry.accession
            ));
        }
        if entry.location_kind == "physical" && entry.house != Some(entry.origin_house) {
            return Err(format!("physical House mismatch: {}", entry.accession));
        }
        if entry.location_kind == "nonphysical_standard"
            && (entry.house.is_some() || entry.point.is_some())
        {
            return Err(format!(
                "nonphysical entity assigned physical Point: {}",
                entry.accession
            ));
        }
    }
    let chromachord = find_record("chromachord").ok_or("ChromaChord missing")?;
    if chromachord.location_kind != "nonphysical_standard" {
        return Err("ChromaChord must remain nonphysical".into());
    }
    let chopera = find_record("the_chopera").ok_or("Chopera missing")?;
    if !chopera
        .relationships
        .iter()
        .any(|link| link.target == Some("the_tross") && link.role == Some("Gremlin of the Chopera"))
    {
        return Err("Tross / Chopera perpetual cultural role missing".into());
    }
    let beck = find_record("the_beck").ok_or("The Beck missing")?;
    if !beck.relationships.iter().any(|link| {
        link.target_houses.contains(&"Sandmanor") && link.target_houses.contains(&"Flynt")
    }) {
        return Err("The Beck cross-House cultural bridge missing".into());
    }
    println!(
        "PASS: 7 founding records; 6 physical sites; 1 nonphysical standard; no constitutional mutation."
    );
    Ok(())
}

fn explore() -> Result<(), String> {
    println!("WARDEN REGISTRAR  ·  interactive read-only browser");
    loop {
        println!();
        index(None, None);
        print!("Record accession/name (q to leave): ");
        io::stdout().flush().map_err(|error| error.to_string())?;
        let mut query = String::new();
        if io::stdin()
            .read_line(&mut query)
            .map_err(|error| error.to_string())?
            == 0
        {
            return Ok(());
        }
        let query = query.trim();
        if query.is_empty() || query.eq_ignore_ascii_case("q") || query.eq_ignore_ascii_case("quit")
        {
            return Ok(());
        }
        match find_record(query) {
            Some(entry) => {
                println!();
                card(entry);
                println!("Press Enter to return to the index.");
                let mut discard = String::new();
                if io::stdin()
                    .read_line(&mut discard)
                    .map_err(|error| error.to_string())?
                    == 0
                {
                    return Ok(());
                }
            }
            None => println!("Unknown record: {query}"),
        }
    }
}

fn run(args: &[String]) -> Result<(), String> {
    match args.first().map(String::as_str) {
        None => {
            if io::stdin().is_terminal() {
                explore()
            } else {
                index(None, None);
                Ok(())
            }
        }
        Some("explore") => {
            if args.len() != 1 {
                return Err("usage: registrar explore".into());
            }
            explore()
        }
        Some("list") => {
            let mut house = None;
            let mut register = None;
            let mut cursor = 1;
            while cursor < args.len() {
                let flag = args[cursor].as_str();
                if cursor + 1 >= args.len() {
                    return Err(format!("missing value for {flag}"));
                }
                let value = args[cursor + 1].as_str();
                match flag {
                    "--house"
                        if ["Stonebend", "Sandmanor", "Glaüshouse", "Flynt"]
                            .iter()
                            .any(|candidate| canon(candidate) == canon(value)) =>
                    {
                        house = Some(value)
                    }
                    "--house" => return Err(format!("unknown House: {value}")),
                    "--register" if ["enterprise", "institutional"].contains(&value) => {
                        register = Some(value)
                    }
                    "--register" => return Err(format!("unknown register: {value}")),
                    _ => return Err(format!("unexpected list argument: {flag}")),
                }
                cursor += 2;
            }
            index(house, register);
            Ok(())
        }
        Some("show") => {
            if args.len() != 2 {
                return Err("usage: registrar show <id|name|key>".into());
            }
            let entry = find_record(&args[1])
                .ok_or_else(|| format!("unknown registered entity: {}", args[1]))?;
            card(entry);
            Ok(())
        }
        Some("verify") if args.len() == 1 => verify(),
        Some("help" | "--help" | "-h") if args.len() == 1 => {
            help();
            Ok(())
        }
        _ => Err("invalid Warden Registrar command; try: registrar help".into()),
    }
}

pub(super) fn maybe_dispatch() {
    let mut args = std::env::args().skip(1);
    let Some(command) = args.next() else {
        return;
    };
    if !["registrar", "warden-registrar"].contains(&command.as_str()) {
        return;
    }
    let subargs: Vec<String> = args.collect();
    if let Err(error) = run(&subargs) {
        eprintln!("Warden Registrar: {error}");
        std::process::exit(2);
    }
    std::process::exit(0);
}

#[cfg(test)]
mod tests {
    use super::*;
    #[test]
    fn founding_records_are_present_and_distinct() {
        assert_eq!(RECORDS.len(), 7);
        assert_eq!(
            RECORDS
                .iter()
                .filter(|r| r.location_kind == "physical")
                .count(),
            6
        );
        assert!(find_record("NOJO").is_some());
        assert!(find_record("WR-002").is_some());
        assert_eq!(find_record("WR-006").unwrap().name, "The Chopera");
        assert!(find_record("The Beck").is_some());
    }
    #[test]
    fn jurisdiction_and_cultural_rules_are_preserved() {
        let chopera = find_record("The Chopera").unwrap();
        assert_eq!(chopera.origin_house, "Flynt");
        assert!(
            chopera
                .relationships
                .iter()
                .any(|r| r.role == Some("Gremlin of the Chopera"))
        );
        assert!(find_record("chromaChord").unwrap().point.is_none());
        assert_eq!(
            find_record("oakwood_studios").unwrap().area,
            Some("Content Farm")
        );
    }
    #[test]
    fn house_normalization_is_equivalent() {
        assert_eq!(canon("Glaüshouse"), canon("glaushouse"));
    }
}
